import{_ as s,c as i,o as e,ap as t}from"./chunks/framework.BVMg0REN.js";const k=JSON.parse('{"title":"零基础开发指南","description":"","frontmatter":{},"headers":[],"relativePath":"Developer/0.0-MaaYuan零基础开发指南.md","filePath":"zh/Developer/0.0-MaaYuan零基础开发指南.md","lastUpdated":1787733673000}'),l={name:"Developer/0.0-MaaYuan零基础开发指南.md"};function r(p,a,o,n,h,d){return e(),i("div",null,a[0]||(a[0]=[t(`<h1 id="零基础开发指南" tabindex="-1"><i class="ri-message-2-line"></i>零基础开发指南 <a class="header-anchor" href="#零基础开发指南" aria-label="Permalink to “零基础开发指南”">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>只有当您想要开发MaaYuan时才需要看当前页面！ 用户请转到 <a href="https://docs.qq.com/aio/DS1BMQmpiQkdOb1RT?pF3pe85z8D7TqvdZcgdqBT=&amp;p=F3pe85z8D7TqvdZcgdqBTF&amp;nlc=1" target="_blank" rel="noreferrer">说明文档</a> 开发 MaaFramework 或开发自己的项目请到 <a href="https://maafw.xyz" target="_blank" rel="noreferrer">MaaXYZ/MaaFramework</a></p><p>本篇文档参考：MaaFW、MAA、M9A开发指南编写！</p><p><a href="https://maafw.com/docs/1.1-QuickStarted" target="_blank" rel="noreferrer">MaaFramework官网</a></p><p><a href="https://docs.maa.plus/zh-cn/develop/development.html#%E5%AE%8C%E6%95%B4%E7%8E%AF%E5%A2%83%E9%85%8D%E7%BD%AE%E6%B5%81%E7%A8%8B-windows" target="_blank" rel="noreferrer">开发指南 | MAA 文档站</a></p><p><a href="https://1999.fan/zh_cn/develop/development.html#%E6%88%91%E6%9C%89%E7%BC%96%E7%A8%8B%E7%BB%8F%E9%AA%8C-%E4%BD%86%E6%98%AF%E6%B2%A1%E5%8F%82%E4%B8%8E%E8%BF%87%E7%9B%B8%E5%85%B3%E9%A1%B9%E7%9B%AE-%E8%A6%81%E6%80%8E%E4%B9%88%E5%81%9A" target="_blank" rel="noreferrer">开发前须知 | M9A 文档站</a></p></div><h2 id="github-pull-request-代码提交流程简述" tabindex="-1">Github Pull Request 代码提交流程简述 <a class="header-anchor" href="#github-pull-request-代码提交流程简述" aria-label="Permalink to “Github Pull Request 代码提交流程简述”">​</a></h2><ul><li><h3 id="我不懂编程-只是想改一点点-json-文件-文档等-要怎么操作" tabindex="-1">我不懂编程，只是想改一点点 JSON 文件/文档等，要怎么操作？ <a class="header-anchor" href="#我不懂编程-只是想改一点点-json-文件-文档等-要怎么操作" aria-label="Permalink to “我不懂编程，只是想改一点点 JSON 文件/文档等，要怎么操作？”">​</a></h3></li></ul><p>欢迎收看 <a href="https://maa.plus/docs/zh-cn/develop/pr-tutorial.html" target="_blank" rel="noreferrer">牛牛也能看懂的 GitHub Pull Request 使用指南</a></p><p>简单来说，就是整个文件夹用VScode打开，找到想编辑的代码在VScode里编辑好，然后把改好的代码粘贴到github网站上进行PR。</p><ul><li><h3 id="我有编程经验-想在本地进行较为完整的项目开发-应该怎么操作" tabindex="-1">我有编程经验，想在本地进行较为完整的项目开发，应该怎么操作？ <a class="header-anchor" href="#我有编程经验-想在本地进行较为完整的项目开发-应该怎么操作" aria-label="Permalink to “我有编程经验，想在本地进行较为完整的项目开发，应该怎么操作？”">​</a></h3></li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li><strong>fork</strong>一份MaaYuan主仓库的代码，并把代码下载到本地；</li><li>在本地写 <code>pipeline</code>、<code>interface</code>、<code>custom</code>文件，利用VSCode插件/小工具/MPE等进行<strong>截图、取ROI</strong>等操作，并利用VSCode插件/MaaDebugger/MPE等调试工具进行<strong>调试</strong>；</li><li>利用git，实现<strong>本地</strong>（电脑硬盘里你的文件夹）-- <strong>个人远程仓库</strong>（你fork的MaaYuan仓库）的交互；</li><li>再利用PR，实现<strong>个人远程仓库</strong>（你fork的MaaYuan仓库）-- <strong>上游原始仓库</strong>（MaaYuan项目仓库）的交互。</li></ul></div><h4 id="_1、前置准备" tabindex="-1">1、前置准备 <a class="header-anchor" href="#_1、前置准备" aria-label="Permalink to “1、前置准备”">​</a></h4><ol><li><p>下载、安装VSCode并安装对应插件</p><p>官网：<a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">https://code.visualstudio.com</a></p><p>推荐下载好后，在扩展里找到 <code>Maa Pipeline Support</code>，进行下载安装。可以进行调试，截图、取ROI等操作，不对的会进行报错提醒。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><ul><li>可以下个代码补全的插件，一键补全，好用！</li><li>代码格式化插件推荐： <code>Prettier</code>，作者Prettier蓝标</li></ul></div></li><li><p>下载并安装git（官网：<a href="https://git-scm.com/" target="_blank" rel="noreferrer">https://git-scm.com/</a> ）</p></li><li><p>下载并安装Python（≥3.11）</p><p>官网：<a href="https://www.python.org/" target="_blank" rel="noreferrer">Welcome to Python.org</a></p></li></ol><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p></p><p>安装教程：</p><p>79 fastinstall发布了一篇小红书笔记，快来看吧！ 😆 q16mTm9mycRvoaa 😆 <a href="http://xhslink.com/a/2lRUfHM42bt6%EF%BC%8C%E5%A4%8D%E5%88%B6%E6%9C%AC%E6%9D%A1%E4%BF%A1%E6%81%AF%EF%BC%8C%E6%89%93%E5%BC%80%E3%80%90%E5%B0%8F%E7%BA%A2%E4%B9%A6%E3%80%91App%E6%9F%A5%E7%9C%8B%E7%B2%BE%E5%BD%A9%E5%86%85%E5%AE%B9%EF%BC%81" target="_blank" rel="noreferrer">http://xhslink.com/a/2lRUfHM42bt6，复制本条信息，打开【小红书】App查看精彩内容！</a></p></div><h4 id="_2、代码配置" tabindex="-1">2、代码配置 <a class="header-anchor" href="#_2、代码配置" aria-label="Permalink to “2、代码配置”">​</a></h4><ol><li><p>如果很久以前 fork 过，先在自己仓库的 <code>Settings</code> 里，翻到最下面，删除。</p></li><li><p>打开 <a href="https://github.com/syoius/MaaYuan" target="_blank" rel="noreferrer">MaaYuan主仓库</a>，点击 <code>Fork</code>，继续点击 <code>Create fork</code></p></li><li><p>按照提示fork好之后，接下来就会来到你的个人仓库，可以看到标题是 <strong>“你的用户名/MaaYuan</strong>”，下面一行小字 <strong>forked from <strong>syoius</strong>/MaaYuan</strong>（复制自 MaaYuan主仓库）</p></li><li><p>克隆你自己的仓库到本地，并拉取子模块</p><p>下了git后，在命令行cmd/powershell中运行</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你的用户</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/MaaYuan.git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">你的用户</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">名</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/MaaYuan.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;F:\\你的文件夹&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   #安装到指定文件夹</span></span></code></pre></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><p><strong>请注意，一定要完整克隆子项目，不要漏了 <code>--recursive</code>，也不要下载 zip 包！</strong></p><p><strong>这步未正确操作会导致所有 OCR（文字识别）失败！</strong></p><p>*MaaCommonAssets子模块：路径为 <code>assets\\MaaCommonAssets</code> 这是一些OCR模型</p></div></li></ol><details><summary><b>如已克隆但发现资源缺失?</b></summary><p>在项目根目录运行以下命令更新子模块：</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> submodule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --recursive</span></span></code></pre></div></details><details><summary><b>想要在指定文件夹下载？</b></summary><p>在你心仪的文件夹右键——<code>在终端中打开</code>/<code>Open git bash here</code>输入git命令。</p><p>或 <code>win</code>+<code>R</code>，输入 <code>cmd</code>后，输入</p><div class="language-cmd"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd /d </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;F:\\你的文件夹&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> #转换默认cmd路径至指定文件夹，powershell和bash的指令可能有所不同</span></span></code></pre></div></details><details><summary><b>我没有下git/git下载不下来/git clone总是失败，怎么办？</b></summary><p>这是因为git clone需要本地代理，没有代理的需要搜索镜像源/在github的镜像网站上下载code的压缩包。</p></details><ol start="5"><li><p>配置OCR文件</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p></p><p>只有配置好OCR文件，才能正常使用调试功能！否则会一直识别不到文字</p></div><p>方法一：将OCR文件解压到 <code>assets/resource/base/model/ocr/</code> 目录下。</p><p>确保路径如下：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">assets/resource/base/model/ocr/</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> det.onnx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">├──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys.txt</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">└──</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rec.onnx</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>OCR文件怎么找：</p><p>如果之前成功下载了子模块：在 <code>assets\\MaaCommonAssets\\OCR\\</code>目录下有OCR文件</p><p>无法成功下载，只下了本体：下载 OCR（文字识别）资源文件 <a href="https://download.maafw.xyz/MaaCommonAssets/OCR/ppocr_v5/ppocr_v5-zh_cn.zip" target="_blank" rel="noreferrer">ppocr_v5.zip</a></p></div><p>方法二：成功下载了子模块，也可直接在根目录下面运行</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/configure.py</span></span></code></pre></div><p>如果成功，提示如下：</p><p>OCR model configured.</p><p>同时在 <code>assets/resource/base/model</code>下可以看到建好的ocr文件夹，里面有装好的ocr文件。</p></li><li><p>下载 MaaFramework 的 <a href="https://github.com/MaaXYZ/MaaFramework/releases" target="_blank" rel="noreferrer">Release 包</a>，解压到 <code>deps</code> 文件夹中。</p></li><li><p>配置编程环境</p></li></ol><ul><li>编程环境：下载好 Python、VS Code，环境就基本配置好啦，接下来就需要选一个 Maa 的开发工具</li><li>Maa 调试/开发工具列表</li></ul><p>工具总览：<a href="https://github.com/MaaXYZ/MaaFramework#%E7%A4%BE%E5%8C%BA%E9%A1%B9%E7%9B%AE" target="_blank" rel="noreferrer">MaaFramework社区项目</a></p><table tabindex="0"><thead><tr><th>工具</th><th>简介</th></tr></thead><tbody><tr><td><a href="https://github.com/MaaXYZ/MaaDebugger" target="_blank" rel="noreferrer">MaaDebugger</a></td><td>独立调试工具</td></tr><tr><td><a href="https://marketplace.visualstudio.com/items?itemName=nekosu.maa-support" target="_blank" rel="noreferrer">Maa Pipeline Support</a></td><td>VSCode 插件，提供调试、截图、获取 ROI、取色等功能</td></tr><tr><td><a href="https://github.com/SweetSmellFox/MFAToolsPlus" target="_blank" rel="noreferrer">MFA Tools Plus</a></td><td>独立截图、获取 ROI、滑动、文字及取色工具</td></tr><tr><td><a href="https://github.com/Windsland52/MAALogAnalyzer" target="_blank" rel="noreferrer">MaaLogAnalyzer</a></td><td>可视化分析基于 MaaFramework 开发应用的日志</td></tr><tr><td><a href="https://mpe.codax.site/stable/" target="_blank" rel="noreferrer">MaaPipelineExtremer - Editor</a></td><td>MPE 网站，可视化编辑和分析 MaaYuan 的流程代码</td></tr></tbody></table><ol start="8"><li><p>开始开发</p><p>使用上一个步骤中安装的开发工具开发MaaYuan，虚拟环境会自动创建在 <code>.venv</code>目录中。</p><p>开始愉快的MaaYuan代码之旅，可以官方文档的使用参考。</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>推荐使用 VSCode 插件进行开发调试、MaaLogAnalyzer 进行用户日志分析、MPE进行流程查看梳理思路</p><p>安装插件后，如果写的时候哪里不对都会<strong>标红</strong>。等vscode里都不红了之后再用Maa Debugger/Maa Pipeline support<strong>调试</strong>看运行流程有没有问题。</p></div><p>参考文档：</p><p><a href="https://maafw.com/docs/3.1-PipelineProtocol" target="_blank" rel="noreferrer">任务流水线（Pipeline）协议 | MaaFramework</a></p><p><a href="https://maafw.com/docs/3.3-ProjectInterfaceV2" target="_blank" rel="noreferrer">Project Interface V2 协议 | MaaFramework</a></p><p><a href="https://maafw.com/docs/2.3-CallbackProtocol" target="_blank" rel="noreferrer">回调协议 | MaaFramework</a></p><p><a href="https://docs.maa.plus/zh-cn/develop/vsc-ext-tutorial.html" target="_blank" rel="noreferrer">专用 VSCode 插件教程 | MAA 文档站</a></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p></p><p>主要要编的代码：</p><p>1、每个任务的代码（pipeline）：在 <code>resource/pipeline</code>下面的 <code>.json</code>文件里（每个任务的单独代码，就是识别到xx点击，接下来再识别xx，编写的规则参照 <code>任务流水线（Pipeline）协议</code></p><p>2、显示在gui上的页面（Interface）：在 <code>interface.json</code>中（任务写好了，想让它显示在gui中，并且能够显示任务说明、选项内容，参照 <code>Project Interface V2 协议</code></p><p>3、选项的实现：在 <code>interface.json</code>中写每个选项对应的 <code>pipeline_override</code>。</p><p>4、日志中消息提醒（focus）：在每个 <code>node</code>中编写 <code>focus</code>信息实现，具体参照节点信息输出和官方文档<a href="https://maafw.com/docs/2.3-CallbackProtocol" target="_blank" rel="noreferrer">回调协议</a></p><p>话不多说，自行看代码更好理解！可参考MaaYuan、M9A的已有代码进行理解</p></div></li><li><p>程序测试</p><p>利用 <code>7. 编程环境</code>中的小工具进行开发，推荐使用VSCode插件，也可使用MaaDebugger调试工具进行测试。选择你编写的代码，进行执行。</p></li><li><p>git 操作（命令行版）</p><p>通常用的最多的基本命令有：</p><ul><li><code>git add &lt;file&gt;</code>：添加文件到暂存区，<code>*</code> 代表全部文件</li><li><code>git commit -m &quot;message&quot;</code>：提交暂存区到本地仓库。<code>message</code> 请遵循 <a href="https://www.conventionalcommits.org/zh-hans/v1.0.0/" target="_blank" rel="noreferrer">约定式提交规范</a>，让你的 commit 信息更加清晰</li><li><code>git pull origin &lt;branch&gt;</code>：拉取远程仓库到本地仓库</li><li><code>git push origin &lt;branch&gt;</code>：推送本地仓库到远程仓库</li></ul><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branch-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 创建并切换到新的分支</span></span></code></pre></div><p>完成开发后，推送你修改的本地分支到远程仓库（fork 的仓库，地址中是你的用户名）</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> origin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">branch-nam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><ul><li>当 MaaYuan仓库出现更改（如其他人的commit），你可能需要把这些更改同步到你的分支</li></ul><p>（1）关联 MaaYuan 原仓库：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/syoius/MaaYuan.git</span></span></code></pre></div><p>（2）拉取远程仓库更新：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span></span></code></pre></div><p>（3）变基（推荐）或者合并修改：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rebase</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream/main</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 变基，使commit历史更清晰，完成你的个人pr时建议使 用rebase而不是merge来合并修改</span></span></code></pre></div><ul><li><p>git 参考资料：</p><ul><li><a href="https://git-scm.com/docs" target="_blank" rel="noreferrer">git 官方文档</a></li><li><a href="https://www.runoob.com/manual/git-guide/" target="_blank" rel="noreferrer">git 简明指南</a></li><li><a href="https://www.runoob.com/git/git-tutorial.html" target="_blank" rel="noreferrer">git 教程|菜鸟教程</a></li></ul></li></ul></li></ol><blockquote><p>不会用命令行？在VSCode里也可以提交！</p><p>ctrl+s进行保存。<code>源代码管理处</code>可以进行拉取（git pull）、暂存（git add）、提交（git commit）、推送（git push）等操作，同命令行操作差不多。</p><p>参照<a href="https://www.bilibili.com/video/BV1Hkr7YYEh8/?share_source=copy_web&amp;vd_source=8bafc3ece922b649199728a9cf446699" target="_blank" rel="noreferrer">给傻子的Git教程_哔哩哔哩_bilibili</a></p></blockquote><ol start="11"><li><p>提交 <strong>Pull Request</strong></p><p>你修改的代码已经提交到你的仓库（github网站上<strong>[你的个人远程仓库]</strong>(<code>https://github.com/&lt;你的用户名&gt;/MaaYuan</code>)，为 <code>origin/&lt;分支名&gt;</code>）。</p><p>现在你需要提交一个 Pull Request 到 MaaYuan的仓库（github上面<a href="https://github.com/syoius/MaaYuan" target="_blank" rel="noreferrer"><em>MaaYuan的总仓库</em></a>，<code>upstream/&lt;分支名&gt;</code>），等待维护者审核。</p><p><a href="https://maa.plus/docs/zh-cn/develop/pr-tutorial.html" target="_blank" rel="noreferrer">GitHub网页端 Pull Request 参考教程</a></p></li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p>PR的基本格式要求（<strong>约定式提交</strong>）：便于我查看和了解你这个代码干了什么，是加了新功能/改了bug/改了文档......</p><p><a href="https://www.conventionalcommits.org/zh-hans/v1.0.0/" target="_blank" rel="noreferrer">约定式提交规范</a></p></div><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p></p><p>开发过程中，每一定数量，记得提交一个 <strong>commit</strong>, 别忘了写上 <strong>message</strong></p><blockquote><p>推荐自动生成提交信息工具：<a href="https://github.com/di-sukharev/opencommit" target="_blank" rel="noreferrer">OpenCommit</a></p></blockquote><p>假如你不熟悉 git 的使用，你可能需要<strong>创建并切换到一个新的分支</strong>，而不是直接提交在 main 上。这样你的提交就能在新的分支上生长，不会受到 main 更新的打扰。</p></div>`,25)]))}const g=s(l,[["render",r]]);export{k as __pageData,g as default};
